export const KNOWLEDGE_LESSONS: KnowledgeLesson[] = [];

// Original bilingual teaching notes; source links are supporting reading, not copied standards.
function lesson(id: string, discipline: string, title: LocalText, summary: LocalText, prerequisites: LocalText, principle: LocalText, practice: LocalText, limits: LocalText, example: LocalText, question: LocalText, options: LocalText[], answer: number, explanation: LocalText, sources: string[]) {
  KNOWLEDGE_LESSONS.push({ id, discipline, title, summary, prerequisites, minutes: 10, sections: [
    { heading: text('المبدأ العلمي', 'Scientific principle'), body: principle },
    { heading: text('التطبيق الهندسي', 'Engineering application'), body: practice },
    { heading: text('الحدود والأخطاء الشائعة', 'Limitations and common mistakes'), body: limits },
  ], example, question, options, answer, explanation, sources });
}

lesson('measurement', 'conventional_ndt', text('القياس والوحدات وعدم اليقين', 'Measurement, units & uncertainty'), text('ابدأ هنا: كيف تتحول قراءة الجهاز إلى نتيجة يمكن الوثوق بها؟', 'Start here: turn an instrument reading into a defensible result.'), text('لا توجد متطلبات سابقة', 'No prerequisites'),
text('القيمة المقاسة ليست القيمة الحقيقية بالضرورة. الدقة تعبر عن قرب القياس من القيمة المرجعية، والتكرارية تعبر عن تقارب القراءات المتكررة. المعايرة تربط الجهاز بمرجع معروف مع توثيق عدم اليقين؛ والتحقق الدوري يؤكد استمرار الأداء ضمن المتطلبات.', 'A measured value is not necessarily the true value. Accuracy describes closeness to a reference; repeatability describes agreement between repeated readings. Calibration relates the instrument to known references with documented uncertainty; periodic verification checks continued performance.'),
text('سجل الوحدة ودقة العرض ورقم الجهاز ومرجع المعايرة وحالة السطح والحرارة. حوّل الوحدات قبل التعويض في المعادلات؛ 1 MHz يساوي مليون Hz و1 mm يساوي 0.001 m. عند الحكم قرب حد القبول، اتبع قاعدة القرار المتفق عليها ولا تتجاهل عدم اليقين.', 'Record units, resolution, instrument ID, calibration reference, surface condition and temperature. Convert units before using equations: 1 MHz is one million Hz and 1 mm is 0.001 m. Near an acceptance boundary, follow the agreed decision rule rather than ignoring uncertainty.'),
text('زيادة الأرقام بعد العلامة العشرية لا تجعل القياس أكثر دقة. تكرار القياس بنفس الخطأ في سرعة الصوت يعطي نتائج متقاربة لكنها منحازة.', 'More decimal places do not improve accuracy. Repeating a measurement with an incorrect sound velocity can produce consistent but biased results.'),
text('قراءات سمك 10.1، 10.2، 10.1 mm: المتوسط نحو 10.13 mm، لكن عرض 10.133333 ليس مبرراً دون معرفة عدم اليقين ودقة الجهاز.', 'Thickness readings of 10.1, 10.2 and 10.1 mm average about 10.13 mm; reporting 10.133333 is not justified without considering uncertainty and resolution.'),
text('هل القراءات المتقاربة تثبت صحة القياس؟', 'Do closely grouped readings prove accuracy?'), [text('نعم دائماً', 'Always'), text('لا؛ قد يوجد انحياز مشترك', 'No; a common bias may remain'), text('فقط إذا كثرت المنازل العشرية', 'Only with many decimal places')], 1, text('التكرارية وحدها لا تستبعد الخطأ المنتظم؛ يلزم مرجع مناسب ومعايرة وتحقق.', 'Repeatability alone does not exclude systematic error; suitable references, calibration and verification are needed.'), ['iso', 'iaea']);

lesson('waves', 'conventional_ndt', text('فيزياء الموجات وحساب زمن الرحلة', 'Wave physics & time of flight'), text('السرعة والتردد والطول الموجي قبل تشغيل UT.', 'Velocity, frequency and wavelength before UT operation.'), text('الوحدات والجبر الأساسي', 'Units and basic algebra'),
text('الموجة الطولية تهتز موازية للانتشار، والقصية عمودياً عليه. العلاقة λ = v/f تربط الطول الموجي بالسرعة والتردد. تتغير السرعة باختلاف المادة ونوع الموجة والحرارة، لذلك لا تستخدم قيمة فولاذ واحدة لكل المواد.', 'Longitudinal waves vibrate parallel to propagation; shear waves vibrate transversely. The relationship λ = v/f connects wavelength, velocity and frequency. Velocity depends on material, wave mode and temperature; one steel value is not universal.'),
text('في pulse-echo يقطع الصوت المسافة إلى العاكس ثم يعود؛ لذا السمك t = v × Δt / 2 بعد تصحيح تأخير المسبار. التردد الأعلى قد يحسن الفصل لكنه يزيد التوهين في بعض المواد. يحدد التطبيق المفاضلة بين الاختراق والدقة.', 'In pulse-echo the wave travels to the reflector and back, so thickness t = v × Δt / 2 after probe-delay correction. Higher frequency can improve resolution but increases attenuation in some materials. The application determines the penetration–resolution trade-off.'),
text('نسيان القسمة على اثنين يضاعف السمك. خشونة السطح والحبيبات الكبيرة وضعف الاقتران قد تخفض الإشارة دون وجود عيب.', 'Omitting the factor of two doubles thickness. Surface roughness, coarse grains and poor coupling can reduce a signal without a flaw.'),
text('عند v = 5920 m/s وf = 4 MHz يكون λ = 1.48 mm. وإذا كان زمن الذهاب والعودة 10 µs فالسمك النظري 29.6 mm.', 'At v = 5920 m/s and f = 4 MHz, λ = 1.48 mm. A 10 µs round-trip time corresponds to a theoretical thickness of 29.6 mm.'),
text('لماذا نقسم زمن الرحلة على اثنين؟', 'Why divide the transit time by two?'), [text('لأن المسار ذهاب وعودة', 'The path is out and back'), text('لتعويض التردد', 'To compensate frequency'), text('لإلغاء التوهين', 'To cancel attenuation')], 0, text('زمن pulse-echo يشمل المسار في الاتجاهين.', 'Pulse-echo time includes both directions.'), ['iaea']);

lesson('vt', 'conventional_ndt', text('الفحص البصري وقراءة الوصلات VT', 'Visual testing & weld geometry'), text('تعرف على العينة قبل اختيار الاختبار التالي.', 'Understand the component before choosing another test.'), text('أساسيات القياس', 'Measurement basics'),
text('الفحص البصري يعتمد على الضوء والرؤية وخط النظر والتباين. يمكنه كشف عدم الاستقامة والتآكل الظاهر وشكل اللحام، لكنه لا يثبت خلو الحجم الداخلي من العيوب.', 'VT relies on lighting, vision, line of sight and contrast. It can reveal misalignment, visible corrosion and weld profile, but cannot establish that the internal volume is defect-free.'),
text('راجع الرسم وهوية المادة ورقم الوصلة ومرحلة الفحص. نظف السطح، تحقق من الإضاءة وأدوات القياس، ثم سجل الموضع والأبعاد بصور ذات مقياس. افصل وصف الملاحظة عن قرار قبولها طبقاً للكود المحدد.', 'Review drawings, material identity, weld ID and inspection stage. Clean the surface, verify lighting and gauges, then record location and dimensions with scaled photographs. Separate the observation from acceptance under the specified code.'),
text('لا تعتبر كل اختلاف شكلي عيباً مرفوضاً، ولا تطبق حدود كود على مشروع يستخدم كوداً آخر. الوصول المحدود قد يستلزم منظاراً أو طريقة مكملة.', 'Not every visible imperfection is rejectable, and limits from one code cannot be transferred to another project. Limited access may require a borescope or complementary method.'),
text('سجل: وصلة W-12، ملاحظة عند الساعة 3، انخفاض سطحي مقاس، أداة القياس ورقمها، ومرجع بند التقييم بدلاً من عبارة «لحام سيئ».', 'Record weld W-12, indication at the 3 o’clock position, measured depression, gauge ID and evaluation clause instead of “bad weld”.'),
text('هل VT وحده يستبعد العيوب الداخلية؟', 'Does VT alone exclude internal flaws?'), [text('نعم', 'Yes'), text('لا', 'No'), text('إذا كان السطح لامعاً', 'If the surface is shiny')], 1, text('الفحص البصري محدود بالأسطح المتاحة وخط الرؤية.', 'VT is limited to accessible surfaces and line of sight.'), ['iaea', 'asnt']);

lesson('pt', 'conventional_ndt', text('السائل النافذ PT: البلل والخاصية الشعرية', 'PT: wetting & capillary action'), text('الكشف عن الانقطاعات المفتوحة على السطح.', 'Detect discontinuities open to the surface.'), text('الفحص البصري والسلامة الكيميائية', 'VT and chemical safety'),
text('يدخل السائل النافذ في الفتحات السطحية بالبلل والخاصية الشعرية. بعد إزالة الزائد يسحب المظهر جزءاً من السائل ليكوّن دلالة مرئية أو فلورية. الطريقة لا تكشف عيباً مغلقاً تحت السطح.', 'Penetrant enters surface openings through wetting and capillary action. After excess removal, developer draws out penetrant to create a visible or fluorescent indication. A closed subsurface flaw cannot be detected.'),
text('التسلسل التعليمي: تنظيف وتجفيف، تطبيق النافذ وزمن مكوث حسب الإجراء، إزالة الزائد دون غسل العيب، تجفيف مناسب ثم مظهر وفحص في ظروف إضاءة محددة. سجل عائلة المواد وحرارة السطح والأزمنة والنتائج.', 'The teaching sequence is cleaning and drying, penetrant application and procedure-defined dwell, excess removal without flushing the flaw, suitable drying, development and inspection under specified lighting. Record product family, surface temperature, times and results.'),
text('الأسطح المسامية أو الطلاء أو تلطيخ المعدن قد تخفي الفتحات أو تزيد الخلفية. لا تختلق أزمنة موحدة لجميع المواد والحرارات؛ ارجع للإجراء ونشرة المنتج واحتياطات التهوية.', 'Porosity, coatings or smeared metal can mask openings or increase background. Do not assume universal dwell times across products and temperatures; use the procedure, product data and ventilation precautions.'),
text('شروخ سطحية في ألومنيوم غير مسامي: PT خيار مناسب؛ MT غير مناسب للألومنيوم لأنه غير حديدي مغناطيسي.', 'Surface cracks in nonporous aluminium: PT is suitable; MT is unsuitable because aluminium is not ferromagnetic.'),
text('أي عيب يناسب PT؟', 'Which flaw suits PT?'), [text('فجوة مغلقة في العمق', 'A sealed deep void'), text('شرخ مفتوح على سطح غير مسامي', 'A surface-breaking crack in nonporous material'), text('كل العيوب دون قيود', 'Every flaw without limitations')], 1, text('يلزم وصول النافذ إلى فتحة العيب.', 'Penetrant must access the flaw opening.'), ['surface']);

lesson('mt', 'conventional_ndt', text('الجسيمات المغناطيسية MT واتجاه المجال', 'MT & magnetic field direction'), text('لماذا تحتاج المغنطة في أكثر من اتجاه؟', 'Why use more than one magnetisation direction?'), text('مبادئ المغناطيسية', 'Basic magnetism'),
text('في المواد الحديدية المغناطيسية يؤدي الانقطاع إلى تسرب الفيض، فتتجمع الجسيمات لتكوين دلالة. حساسية الكشف تعتمد على اتجاه العيب بالنسبة للمجال؛ الانقطاع الأقرب إلى العمودية على المجال عادة أسهل كشفاً.', 'In ferromagnetic materials a discontinuity can cause flux leakage, attracting particles into an indication. Sensitivity depends on flaw orientation relative to the field; a discontinuity closer to perpendicular is generally easier to detect.'),
text('تحقق من صلاحية الجهاز وكفاية المجال واتجاهه وفق الإجراء. افحص باتجاهين مناسبين لتقليل احتمال فقد عيوب موازية للمجال الأول، وراقب الإضاءة وتركيز المعلق وحالة السطح. قد تلزم إزالة مغنطة بعد الفحص.', 'Verify equipment performance, field adequacy and direction under the procedure. Inspect in suitable directions to reduce missed flaws parallel to the first field; control lighting, suspension concentration and surface condition. Demagnetisation may be required afterwards.'),
text('MT لا يصلح لكل المعادن؛ معظم أنواع الستانلس الأوستنيتي والألومنيوم لا تناسبه. الدلالات قرب تغيرات الشكل قد تكون هندسية وليست شروخاً.', 'MT is not suitable for all metals; most austenitic stainless steels and aluminium are unsuitable. Indications near geometry changes may be nonrelevant rather than cracks.'),
text('إذا كان المجال الأول طولياً، أعد الفحص بمجال عرضي مناسب طبقاً للإجراء بدلاً من افتراض أن فحصاً واحداً يكشف جميع الاتجاهات.', 'If the initial field is longitudinal, use a suitable transverse field under the procedure rather than assuming one direction detects all flaws.'),
text('أي مادة مناسبة عادةً لـ MT؟', 'Which material is generally suitable for MT?'), [text('ألومنيوم', 'Aluminium'), text('زجاج', 'Glass'), text('فولاذ كربوني حديدي مغناطيسي', 'Ferromagnetic carbon steel')], 2, text('الطريقة تحتاج مادة قابلة للمغنطة الحديدية.', 'The method requires a ferromagnetic material.'), ['surface']);

lesson('ut', 'conventional_ndt', text('UT: المعايرة وتفسير A-scan', 'UT: calibration & A-scan interpretation'), text('فرّق بين صدى العيب وصدى الشكل الهندسي.', 'Distinguish flaw echoes from geometry echoes.'), text('درس فيزياء الموجات', 'Wave physics lesson'),
text('عرض A-scan يربط سعة الإشارة بزمن الرحلة أو المسافة المحولة منه. شدة الصدى تتأثر بالحجم والاتجاه والمسافة والاقتران؛ لذلك ارتفاع الإشارة وحده ليس قياساً مباشراً لحجم العيب.', 'An A-scan plots signal amplitude against transit time or derived distance. Echo amplitude depends on size, orientation, distance and coupling; amplitude alone is not a direct flaw-size measurement.'),
text('اضبط التأخير والسرعة والمدى والحساسية باستخدام مرجع مناسب. تحقق من نقطة خروج وزاوية المسبار عند الفحص الزاوي، ثم افحص التغطية من اتجاهات مناسبة وسجل مسار الصوت والموضع واستجابة المرجع.', 'Set delay, velocity, range and sensitivity using a suitable reference. For angle-beam testing verify probe index and angle, examine coverage from appropriate directions and record sound path, position and reference response.'),
text('DAC وTCG وسائل لتعويض تغير الاستجابة مع المسافة ضمن إعداد محدد وليسا معيار قبول مستقلين. التمييز بين صدى الجذر والشرخ يحتاج معرفة الرسم وحركة الإشارة ومسحاً تكميلياً.', 'DAC and TCG compensate distance-dependent response within a defined setup; neither is an independent acceptance standard. Distinguishing root geometry from a crack requires drawings, echo movement and complementary scanning.'),
text('مسار صوت 50 mm بزاوية 60° من العمود: العمق النظري في الرجل الأولى = 50 cos60° = 25 mm، والمسافة السطحية ≈ 43.3 mm.', 'A 50 mm sound path at 60° from the normal gives a first-leg depth of 50 cos60° = 25 mm and surface projection about 43.3 mm.'),
text('هل أعلى صدى يعني دائماً أكبر عيب؟', 'Does the highest echo always mean the largest flaw?'), [text('نعم', 'Yes'), text('لا؛ الاتجاه والاقتران يؤثران', 'No; orientation and coupling matter'), text('نعم عند أي تردد', 'Yes at any frequency')], 1, text('السعة تعتمد على عوامل عديدة وليست على الحجم وحده.', 'Amplitude depends on multiple factors, not size alone.'), ['iaea']);

lesson('rt', 'conventional_ndt', text('RT: تكوين الصورة وجودتها', 'RT: image formation & quality'), text('التوهين والتباين وIQI دون تشغيل مصدر إشعاعي.', 'Attenuation, contrast and IQIs without operating a radiation source.'), text('أساسيات الفيزياء والسلامة الإشعاعية', 'Basic physics and radiation safety'),
text('التصوير الإشعاعي يسجل اختلاف توهين الأشعة خلال المادة على فيلم أو كاشف رقمي. التوهين يتغير مع الطاقة والكثافة والسمك. الصورة إسقاط ثنائي الأبعاد لحجم ثلاثي الأبعاد؛ تراكب الأشكال واتجاه الشروخ يؤثران في الكشف.', 'Radiography records differences in radiation attenuation on film or a digital detector. Attenuation depends on energy, density and thickness. The image is a two-dimensional projection of a three-dimensional volume; superposition and crack orientation affect detection.'),
text('راجع تعريف الصورة والتغطية وجودة الصورة وظهور IQI وفق التقنية والإجراء المعتمد قبل تقييم الدلالات. تحقق من التباين وعدم الحدة وآثار المعالجة. افصل صلاحية الصورة عن قبول اللحام.', 'Check image identification, coverage, image quality and IQI visibility against the approved technique and procedure before evaluating indications. Assess contrast, unsharpness and processing artefacts. Image validity and weld acceptance are separate decisions.'),
text('ظهور IQI لا يضمن كشف كل شرخ، والصورة الداكنة ليست دليلاً كافياً على الجودة. هذا شرح نظري فقط؛ تشغيل المصادر أو تحديد مناطق العزل عمل لمختصين مرخصين.', 'A visible IQI does not guarantee detection of every crack, and a dark image alone does not prove quality. This is theory only; source operation and controlled-area design require authorised specialists.'),
text('دلالة داكنة مستديرة قد تتفق مع مسامية، لكن يلزم استبعاد أثر الفيلم والتحقق من الموقع والشكل قبل التصنيف والتقييم.', 'A rounded dark indication may be consistent with porosity, but film artefacts must be excluded and location and shape checked before classification and evaluation.'),
text('ما دور IQI؟', 'What is an IQI used for?'), [text('ضمان عدم وجود أي عيب', 'Guaranteeing no flaws exist'), text('إثبات مستوى محدد من جودة الصورة', 'Demonstrating specified image quality'), text('تحديد الجرعة الشخصية', 'Measuring personal dose')], 1, text('IQI مؤشر جودة صورة وليس ضماناً لكشف كل عيب أو مقياس جرعة.', 'An IQI indicates image quality, not universal flaw detection or personal dose.'), ['iaea', 'safety']);

lesson('et', 'ndt_advanced', text('ET: الحث الكهرومغناطيسي والتيارات الدوامية', 'ET: electromagnetic induction & eddy currents'), text('اختبار المواد الموصلة ومفهوم عمق الاختراق.', 'Conductive-material testing and penetration depth.'), text('مبادئ الكهرباء والمغناطيسية', 'Basic electricity and magnetism'),
text('ملف بتيار متردد يولد مجالاً يثير تيارات دوامية في مادة موصلة. العيوب وتغيرات التوصيلية والنفاذية والمسافة بين الملف والسطح تغير ممانعة الملف. يتركز التيار قرب السطح بسبب التأثير الجلدي.', 'An alternating-current coil induces eddy currents in a conductive material. Flaws, conductivity, permeability and coil-to-surface spacing change coil impedance. Skin effect concentrates current near the surface.'),
text('اختر المسبار والتردد والمرجع لنوع المادة والعيب المستهدف، واضبط الرفع lift-off والاستجابة المرجعية. التردد الأعلى يقلل عمق الاختراق القياسي غالباً؛ مزج الترددات قد يساعد على فصل المتغيرات في تطبيقات الأنابيب.', 'Select probe, frequency and reference for the material and target flaw. Balance lift-off and reference response. Higher frequency generally reduces standard penetration depth; frequency mixing can help separate variables in tube applications.'),
text('تغير الإشارة لا يعني دائماً شرخاً؛ قد ينشأ من رفع المسبار أو اختلاف المعالجة الحرارية أو النفاذية. لا يصلح ET التقليدي للمواد غير الموصلة.', 'A changed signal is not necessarily a crack; lift-off, heat treatment or permeability may be responsible. Conventional ET is unsuitable for nonconductors.'),
text('عند زيادة التردد أربعة أمثال مع ثبات التوصيلية والنفاذية، ينخفض عمق الاختراق القياسي إلى النصف لأن δ يتناسب عكسياً مع الجذر التربيعي للتردد.', 'Quadrupling frequency at constant conductivity and permeability halves standard penetration depth because δ varies inversely with the square root of frequency.'),
text('أي متغير قد يقلد دلالة عيب؟', 'Which variable can mimic a flaw indication?'), [text('رفع المسبار عن السطح', 'Probe lift-off'), text('اسم المفتش', 'Inspector name'), text('رقم التقرير فقط', 'Report number alone')], 0, text('الـ lift-off يغير الاقتران الكهرومغناطيسي والاستجابة.', 'Lift-off changes electromagnetic coupling and response.'), ['iaea', 'asnt']);

lesson('paut', 'ndt_advanced', text('PAUT: التأخيرات وقوانين التركيز', 'PAUT: delays & focal laws'), text('من عناصر المصفوفة إلى خطة تغطية اللحام.', 'From array elements to a weld coverage plan.'), text('UT والمعايرة والانكسار', 'UT, calibration and refraction'),
text('تُثار عناصر المصفوفة بتأخيرات محسوبة لتوجيه الحزمة وتركيزها. المسح القطاعي يجمع زوايا متعددة؛ والمسح الخطي يحرك الفتحة الفعالة إلكترونياً. الصورة الملونة تمثيل لبيانات صوتية وليست صورة فوتوغرافية للعيب.', 'Calculated delays steer and focus the array beam. Sectorial scanning collects multiple angles; linear scanning moves the active aperture electronically. The colour display represents acoustic data, not a photograph of the flaw.'),
text('ابدأ بالرسم والسمك وشطفة اللحام والعيوب المستهدفة، ثم صمم خطة المسح وحدد المسبار والإسفين والفتحة والزوايا والتغطية. تحقق من العناصر وتأخير الإسفين والحساسية وموضع المشفر واحتفظ بالبيانات الخام.', 'Start with drawings, thickness, bevel and target flaws, then design the scan plan and select probe, wedge, aperture, angles and coverage. Verify elements, wedge delay, sensitivity and encoder position; preserve raw data.'),
text('المناطق غير المغطاة وضعف الاقتران وظلال الهندسة قد تنتج ثقة زائفة. تعدد الزوايا لا يضمن اكتشاف كل اتجاه أو إزالة كل منطقة ميتة.', 'Uncovered regions, poor coupling and geometry shadows can create false confidence. Multiple angles do not guarantee every orientation is detected or eliminate all dead zones.'),
text('في وصلة على شكل V، ارسم مسارات الحزم نحو وجهي الشطفة والجذر وتحقق بعاكسات مرجعية ممثلة؛ لا تعتمد على منظر S-scan الجميل وحده.', 'For a V-groove weld, plot beam paths to both bevel faces and the root and verify representative reflectors; an attractive S-scan alone is insufficient.'),
text('ما وظيفة focal laws؟', 'What do focal laws control?'), [text('لون الطلاء', 'Coating colour'), text('تأخيرات العناصر لتوجيه وتركيز الحزمة', 'Element delays for beam steering and focusing'), text('قبول جميع الدلالات', 'Acceptance of all indications')], 1, text('تُحسب التأخيرات لتشكيل الحزمة؛ القبول يرجع للكود.', 'Delays shape the beam; acceptance comes from the governing code.'), ['paut', 'iaea']);

lesson('tofd', 'ndt_advanced', text('TOFD: الحيود والمناطق القريبة من السطح', 'TOFD: diffraction & near-surface zones'), text('تقدير ارتفاع العيب من أزمنة إشارات أطرافه.', 'Estimate flaw height from tip-signal arrival times.'), text('الموجات وUT وهندسة المثلثات', 'Waves, UT and trigonometry'),
text('يرسل مسبار وتستقبل وحدة مقابلة الإشارات المحيدة من أطراف العيب. تُستخدم أزمنة الوصول وهندسة المسابير لتقدير العمق والارتفاع بدلاً من الاعتماد أساساً على سعة الصدى.', 'A transmitter and an opposing receiver collect signals diffracted from flaw tips. Arrival times and probe geometry estimate depth and height rather than relying primarily on echo amplitude.'),
text('حدد فصل المسابير والتغطية والمرجع وسرعة الصوت. تعرف على الموجة الجانبية وصدى الجدار الخلفي، ثم ابحث عن إشارات الأطراف مع مراعاة جودة الاقتران والتحقق من التوقيت والمشفر.', 'Define probe separation, coverage, reference and velocity. Identify the lateral wave and backwall signal, then interpret tip signals while checking coupling, timing and encoder performance.'),
text('تداخل الإشارات قرب السطح أو الجدار الخلفي يحد الكشف في بعض المناطق. قد تحتاج PAUT أو فحصاً سطحياً مكملاً؛ TOFD ليس بديلاً تلقائياً لكل متطلبات الفحص.', 'Signal overlap near the surface or backwall limits detection in some regions. PAUT or surface testing may be needed; TOFD is not automatically a replacement for all inspection requirements.'),
text('إذا ظهر طرف علوي عند عمق 12 mm وسفلي عند 17 mm، فالارتفاع المقدر 5 mm، بشرط صحة تحديد الإشارات والمعايرة.', 'If the upper tip is at 12 mm and the lower at 17 mm, estimated height is 5 mm, provided signal identification and calibration are valid.'),
text('ما الإجراء الأنسب لمنطقة محدودة التغطية قرب السطح؟', 'What is appropriate for limited near-surface coverage?'), [text('اعتبارها سليمة تلقائياً', 'Automatically declare it sound'), text('تجاهلها', 'Ignore it'), text('استخدام طريقة مكملة موثقة', 'Use a documented complementary method')], 2, text('حدود الكشف يجب معالجتها بخطة فحص لا بافتراض السلامة.', 'Detection limitations require an inspection plan, not an assumption of soundness.'), ['tofd']);

lesson('materials', 'pwht_metallurgy', text('علم المعادن والبنية المجهرية', 'Metallurgy & microstructure'), text('اربط التبريد والصلادة والمتانة بقابلية اللحام.', 'Connect cooling, hardness and toughness with weldability.'), text('مبادئ المواد والحرارة', 'Basic materials and heat'),
text('خواص الفولاذ تعتمد على التركيب الكيميائي والبنية المجهرية وتاريخ التصنيع. قد ينتج التبريد السريع بنى أكثر صلادة في أنواع قابلة للتصلد. منطقة HAZ تتغير حرارياً دون أن تنصهر بالكامل، وتختلف خواصها عن معدن الأساس واللحام.', 'Steel properties depend on chemistry, microstructure and manufacturing history. Rapid cooling can produce harder structures in hardenable steels. The HAZ is thermally altered without fully melting and can differ from both weld and parent metal.'),
text('راجع شهادة المادة وربطها بالقطعة، ثم قيم متطلبات التسخين المسبق وحرارة ما بين الطبقات والمعالجة وفق WPS والكود. اختبارات الصلادة وPMI والمجهر تكمل بعضها؛ ولا يعطي أي منها بمفرده تعريفاً كاملاً للخواص.', 'Trace the material certificate to the component, then assess preheat, interpass and treatment requirements under the WPS and code. Hardness, PMI and microscopy complement each other; none alone fully characterises properties.'),
text('الصلادة ليست المتانة. كما أن تحويلات الصلادة تقريبية وتعتمد على المادة والطريقة؛ لا تستنتج مقاومة كسر مؤكدة من قراءة واحدة.', 'Hardness is not toughness. Hardness conversions are approximate and material- and method-dependent; a single reading cannot establish fracture resistance.'),
text('منطقتان لهما تركيب كيميائي متقارب قد تختلف صلادتهما بسبب اختلاف تاريخ التبريد؛ راجع التاريخ الحراري قبل استنتاج خطأ في هوية المادة.', 'Two regions of similar chemistry may have different hardness due to cooling history; examine thermal history before assuming material misidentification.'),
text('هل الصلادة والمتانة خاصية واحدة؟', 'Are hardness and toughness the same property?'), [text('لا', 'No'), text('نعم دائماً', 'Always'), text('في كل أنواع الفولاذ', 'In all steels')], 0, text('الصلادة مقاومة للتشوه الموضعي، والمتانة مرتبطة بامتصاص الطاقة ومقاومة الكسر.', 'Hardness concerns local deformation resistance; toughness concerns energy absorption and fracture resistance.'), ['welding', 'hydrogen']);

lesson('wps', 'welding_inspection', text('WPS وPQR وتأهيل اللحّام', 'WPS, PQR & welder qualification'), text('ثلاث وثائق مختلفة لا تحل إحداها محل الأخرى.', 'Three distinct records with different purposes.'), text('عمليات اللحام وعلم المعادن', 'Welding processes and metallurgy'),
text('WPS تعليمات الإنتاج ضمن نطاق محدد. PQR يسجل ظروف اختبار تأهيل الإجراء ونتائجه. تأهيل اللحّام يثبت القدرة على تنفيذ لحامات ضمن نطاق التأهيل المعتمد؛ لا يثبت وحده صلاحية كل إجراء.', 'The WPS gives production instructions within a defined range. The PQR records procedure-qualification test variables and results. Welder qualification demonstrates performance within its qualified range, not the validity of every procedure.'),
text('قبل اللحام تحقق من توافق العملية والمادة والسمك والوضعية ومعدن الحشو ومتطلبات الحرارة مع الوثائق المطبقة. أثناء التنفيذ راقب المتغيرات المحددة وسجل أي خروج، ثم اتبع ITP للفحوص التالية.', 'Before welding check process, material, thickness, position, filler and thermal requirements against applicable documents. Monitor specified variables during production, record deviations and follow the ITP for subsequent inspections.'),
text('نطاقات التأهيل تختلف حسب كود المشروع والإصدار. لا تستخدم جدولاً عاماً بديلاً عن مراجعة المتغيرات الأساسية والإضافية ومتطلبات الخدمة.', 'Qualification ranges differ by project code and edition. Generic tables cannot replace review of essential, supplementary and service-specific requirements.'),
text('وجود لحّام مؤهل لا يبرر استخدام WPS غير مناسب لمجموعة المادة أو العملية المطلوبة؛ يلزم التحقق من كلا النطاقين.', 'A qualified welder does not justify an unsuitable WPS for the material group or process; both ranges must be checked.'),
text('أي وثيقة تسجل القيم الفعلية لاختبار تأهيل الإجراء؟', 'Which record contains actual procedure qualification test variables?'), [text('PQR', 'PQR'), text('صورة اللحام', 'A weld photograph'), text('قائمة الحضور', 'An attendance sheet')], 0, text('PQR سجل الاختبار، أما WPS فتعليمات التنفيذ.', 'The PQR records the test; the WPS gives execution instructions.'), ['iaea', 'welding']);

lesson('heat', 'welding_inspection', text('طاقة القوس ومدخل الحرارة', 'Arc energy & heat input'), text('مثال حسابي بوحدات صحيحة وحدود واضحة.', 'A worked example with correct units and clear limits.'), text('الجبر والكهرباء الأساسية', 'Basic algebra and electricity'),
text('طاقة القوس لكل وحدة طول عند سرعة بوحدة mm/min تساوي V × I × 60 / (1000 × s) بوحدة kJ/mm. بعض المراجع تعرف مدخل الحرارة بضرب طاقة القوس في كفاءة العملية η؛ يجب معرفة تعريف الكود قبل المقارنة.', 'With travel speed in mm/min, arc energy per unit length is V × I × 60 / (1000 × s) in kJ/mm. Some references define heat input by multiplying arc energy by process efficiency η; establish the code definition before comparing values.'),
text('قِس الجهد والتيار وسرعة الحركة بطريقة مناسبة، وراجع حدود WPS. في العمليات النبضية قد لا يكفي حاصل ضرب متوسط الجهد في متوسط التيار لتقدير القدرة الفعلية.', 'Measure voltage, current and travel speed appropriately and check WPS limits. For pulsed processes, multiplying average voltage by average current may not adequately estimate actual power.'),
text('الزيادة ليست أفضل دائماً؛ قد تؤثر الطاقة على البنية والمتانة والتشوه. لا تخلط mm/s مع mm/min أو تستخدم كفاءة افتراضية بوصفها قيمة معتمدة.', 'Higher is not always better: energy affects microstructure, toughness and distortion. Do not confuse mm/s with mm/min or treat an assumed efficiency as an approved value.'),
text('24 V، 140 A، 180 mm/min تعطي طاقة قوس 1.12 kJ/mm. عند افتراض η = 0.8 يصبح مدخل الحرارة 0.896 kJ/mm؛ الافتراض للتعليم وليس لإقرار إجراء.', '24 V, 140 A and 180 mm/min give arc energy of 1.12 kJ/mm. Assuming η = 0.8 gives 0.896 kJ/mm heat input; this assumption is educational, not procedure approval.'),
text('ماذا يحدث لطاقة القوس عند مضاعفة السرعة مع ثبات V وI؟', 'What happens to arc energy when speed doubles at fixed V and I?'), [text('تتضاعف', 'It doubles'), text('تنخفض إلى النصف', 'It halves'), text('لا تتغير', 'It is unchanged')], 1, text('السرعة في مقام المعادلة.', 'Speed is in the denominator.'), ['welding', 'hydrogen']);

lesson('pwht', 'pwht_metallurgy', text('PWHT والتسخين المسبق: أهداف مختلفة', 'PWHT & preheat: different objectives'), text('قراءة منحنى حراري لا إعداد وصفة تشغيل.', 'Read a thermal chart, not a universal operating recipe.'), text('علم المعادن وWPS', 'Metallurgy and WPS'),
text('التسخين المسبق يبطئ التبريد وقد يساعد خروج الهيدروجين ويقلل البنية الحساسة للشروخ. المعالجة بعد اللحام قد تستهدف تقليل الإجهادات أو مراجعة البنية حسب نوع السبيكة. إزالة الهيدروجين ليست مرادفاً تلقائياً لكل PWHT.', 'Preheat slows cooling and can promote hydrogen escape and reduce crack-sensitive structures. PWHT may relieve stresses or temper microstructure depending on alloy. Hydrogen removal is not automatically synonymous with every PWHT cycle.'),
text('راجع المادة والسمك والتقييد والكود وWPS وإجراء المعالجة المعتمد. اقرأ منحنى التسخين والمكوث والتبريد، توزيع الترموكبلات، معايرة المسجل وتجانس الحرارة. وثق أي انقطاع وقدمه للمسؤول الفني.', 'Review material, thickness, restraint, code, WPS and approved treatment procedure. Examine ramps, soak, cooling, thermocouple distribution, recorder calibration and temperature uniformity. Document interruptions for technical review.'),
text('لا توجد درجة أو ساعة لكل بوصة تصلح لكل الحالات. معالجة غير مناسبة قد تضر المتانة أو خواص سبائك معينة؛ منحنى المحاكاة ليس تعليمات موقع.', 'No single temperature or hours-per-inch rule covers all cases. Inappropriate treatment can damage toughness or alloy properties; a simulated curve is not a site instruction.'),
text('إذا حقق ترموكبل واحد المكوث المطلوب بينما آخر لم يحققه، فلا تعتمد الدورة من متوسط القراءتين؛ راجع متطلبات التجانس والإجراء.', 'If one thermocouple achieves the required soak and another does not, do not approve the cycle from their average; review uniformity and procedure requirements.'),
text('هل يكفي السمك وحده لاختيار دورة PWHT؟', 'Is thickness alone sufficient to select a PWHT cycle?'), [text('نعم دائماً', 'Always'), text('نعم مع أي سبيكة', 'Yes for every alloy'), text('لا؛ المادة والكود والإجراء عوامل أساسية', 'No; material, code and procedure are essential')], 2, text('الدورة تتحدد بمجموعة متطلبات لا بمعامل عام واحد.', 'The cycle depends on a set of requirements, not a single generic factor.'), ['hydrogen', 'welding']);

lesson('corrosion', 'coating_corrosion', text('التآكل وآليات التلف', 'Corrosion & damage mechanisms'), text('حدد الآلية قبل تحديد وسيلة القياس.', 'Identify the mechanism before choosing measurement.'), text('أساسيات المواد والكيمياء', 'Basic materials and chemistry'),
text('التآكل الكهروكيميائي يحتاج مناطق أنودية وكاثودية ومساراً إلكترونياً وإلكتروليتاً. الفقد قد يكون عاماً أو موضعياً مثل التنقر، وقد تحدث شروخ مرتبطة بالبيئة والإجهاد. ليست كل آليات التلف فقداً منتظماً للسمك.', 'Electrochemical corrosion involves anodic and cathodic regions, an electronic path and an electrolyte. Loss may be general or localised, such as pitting; environmental and stress-assisted cracking can also occur. Not every damage mechanism produces uniform thinning.'),
text('اجمع بيانات المادة والمائع والحرارة والتاريخ التشغيلي. حدد المواقع الأكثر تعرضاً ثم اختر قياسات سمك أو خرائط تآكل أو فحوص شروخ بحسب الآلية. اربط النتائج بخريطة مواقع قابلة للتكرار.', 'Collect material, fluid, temperature and operating-history data. Identify susceptible locations, then select thickness readings, corrosion mapping or crack examinations to match the mechanism. Link results to reproducible locations.'),
text('متوسط السمك قد يخفي حفرة عميقة، كما أن قياس السمك وحده لا يستبعد SCC. لا تعمم معدل تآكل واحداً على كل دوائر الخدمة.', 'Average thickness can hide a deep pit, and thickness testing alone cannot exclude SCC. Do not apply one corrosion rate to all service circuits.'),
text('شبكة قياسات واسعة قد تفوت تآكلاً موضعياً صغير المساحة؛ يمكن أن تستلزم الحالة مسحاً أدق أو طريقة تصوير مناسبة.', 'A coarse measurement grid may miss small localised attack; finer mapping or suitable imaging may be required.'),
text('هل متوسط السمك يستبعد التنقر العميق؟', 'Does average thickness exclude deep pitting?'), [text('لا', 'No'), text('نعم', 'Yes'), text('إذا زاد عدد التقارير', 'If there are more reports')], 0, text('الفقد الموضعي يتطلب توصيفاً محلياً وليس متوسطاً فقط.', 'Localised loss requires local characterisation, not only an average.'), ['api', 'rbi', 'ampp']);

lesson('coating', 'coating_corrosion', text('فحص الدهانات وتجهيز السطح', 'Coating inspection & surface preparation'), text('النظافة والخشونة والبيئة والسماكة منظومة واحدة.', 'Cleanliness, profile, environment and thickness form one system.'), text('القياس والتآكل', 'Measurement and corrosion'),
text('الطلاء يعمل حاجزاً واقياً، لكن أداءه يعتمد على الالتصاق ونظافة السطح والخشونة والتوافق والإنضاج. سماكة جيدة على سطح ملوث لا تعني نظام حماية جيداً.', 'A coating acts as a protective barrier, but performance depends on adhesion, surface cleanliness and profile, compatibility and curing. Good thickness on a contaminated surface does not establish a sound protective system.'),
text('راجع مواصفة المشروع ونشرة المنتج. افحص النظافة والأملاح والغبار والخشونة والظروف البيئية قبل التطبيق، ثم الخلط ومدة الاستخدام والسماكة الرطبة والجافة والإنضاج. قارن DFT بخطة أخذ القراءات المعتمدة.', 'Review project specifications and product data. Check cleanliness, salts, dust, profile and environmental conditions before application, then mixing, pot life, wet and dry thickness and cure. Evaluate DFT against the approved sampling plan.'),
text('لا تعتمد حداً واحداً لفارق نقطة الندى أو سماكة لكل المنتجات. اختبار المسامية الكهربائي يحتاج نوعاً وجهداً مناسبين للنظام وإجراءات سلامة؛ لا يستخدم عشوائياً.', 'Do not assume a single dew-point margin or thickness limit for every product. Holiday testing requires suitable equipment, voltage and safety controls for the coating system; it is not applied indiscriminately.'),
text('إذا كانت سماكة الدهان مقبولة لكن تجهيز السطح لم يوثق، فملف الجودة غير مكتمل؛ اطلب أدلة المرحلة السابقة ولا تعتمد السماكة وحدها.', 'If DFT is acceptable but surface preparation was not documented, the quality record is incomplete; seek evidence rather than relying on thickness alone.'),
text('هل DFT وحده يثبت جودة نظام الدهان؟', 'Does DFT alone prove coating-system quality?'), [text('نعم', 'Yes'), text('لا؛ تجهيز السطح والبيئة والإنضاج مهمون', 'No; preparation, environment and curing matter'), text('دائماً في الخارج', 'Always outdoors')], 1, text('الحماية نتيجة سلسلة مراحل مترابطة.', 'Protection results from linked preparation and application stages.'), ['ampp']);

lesson('remaining-life', 'api_inspection', text('معدل التآكل والعمر المتبقي: مثال تعليمي', 'Corrosion rate & remaining life: teaching example'), text('تعلم الحساب دون تحويله إلى تصريح تشغيل.', 'Learn the calculation without treating it as operating approval.'), text('القياس والتآكل والجبر', 'Measurement, corrosion and algebra'),
text('معدل الفقد البسيط CR = (t_old − t_now) / Δyears بوحدة mm/year، بشرط قابلية مقارنة المواضع والقياسات. العمر الاسمي المبسط RL = (t_now − t_required) / CR عندما CR موجب؛ السمك المطلوب تحدده مراجعة هندسية وفق الكود.', 'A simple loss rate is CR = (t_old − t_now) / Δyears in mm/year, provided readings and locations are comparable. Simplified nominal life is RL = (t_now − t_required) / CR for positive CR; required thickness comes from an engineering code assessment.'),
text('راجع قراءات قصيرة وطويلة المدى وصحة بيانات التشغيل والتغيرات في الآلية. افصل العمر المحسوب عن موعد الفحص الذي تحكمه متطلبات الكود والمخاطر وحدود أخرى. أدخل عدم اليقين والتآكل الموضعي في المراجعة.', 'Review short- and long-term readings, operating data and changes in mechanism. Separate calculated life from inspection intervals governed by code, risk and other limits. Include uncertainty and local damage in the review.'),
text('CR صفر أو سالب لا يعني عمراً لا نهائياً؛ قد يعكس خطأ قياس أو اختلاف الموضع. المعادلة المبسطة لا تغطي الشروخ أو الزحف أو الانبعاج أو كل تفاصيل الأنابيب.', 'Zero or negative CR does not mean infinite life; it can reflect measurement or location differences. The simplified equation does not cover cracking, creep, buckling or all piping details.'),
text('سمك قديم 10 mm وحالي 9 mm بعد 5 سنوات: CR = 0.2 mm/year. مع سمك مطلوب افتراضي 7 mm يكون RL = 10 سنوات؛ هذا ليس تصريحاً بالتشغيل 10 سنوات أو موعد فحص معتمداً.', 'From 10 mm to 9 mm in five years, CR = 0.2 mm/year. With a hypothetical required thickness of 7 mm, RL = 10 years; this is neither ten-year operating approval nor an approved inspection interval.'),
text('ماذا تفعل عند معدل تآكل سالب؟', 'What should you do with a negative corrosion rate?'), [text('تعلن عمراً لا نهائياً', 'Declare infinite life'), text('تراجع البيانات والمواضع وعدم اليقين', 'Review data, locations and uncertainty'), text('تلغي كل الفحوص', 'Cancel all inspections')], 1, text('الزيادة الظاهرية قد تكون اختلاف قياس وليست استعادة معدن.', 'Apparent thickness gain can be measurement variation rather than metal recovery.'), ['api']);

lesson('rbi', 'asset_integrity_rope', text('RBI وFFS: الأولويات وصلاحية الخدمة', 'RBI & FFS: priorities and service fitness'), text('المخاطر ليست مجرد ترتيب حسب العمر.', 'Risk is more than an age-based ranking.'), text('آليات التلف والتفتيش أثناء الخدمة', 'Damage mechanisms and in-service inspection'),
text('RBI يربط احتمال الفشل بعواقبه لتوجيه خطة الفحص. FFS يقيّم صلاحية مكون به تلف معروف باستخدام منهج هندسي مناسب. تقليل عدم اليقين بالفحص لا يزيل التلف الموجود بنفسه.', 'RBI combines failure likelihood and consequences to guide inspection planning. FFS assesses the fitness of a component with known damage using an appropriate engineering method. Inspection can reduce uncertainty but does not itself remove damage.'),
text('حدد حدود النظام وآليات التلف وجودة البيانات والعواقب على الأفراد والبيئة والإنتاج. اختر فحصاً فعالاً لكل آلية، وحدد مسؤوليات تحديث التقييم بعد تغير الخدمة أو ظهور نتائج جديدة.', 'Define system boundaries, damage mechanisms, data quality and consequences for people, environment and production. Choose effective inspection for each mechanism and assign responsibility for reassessment after service changes or new findings.'),
text('مصفوفة ألوان وحدها ليست دراسة RBI، وفحص ممتاز لآلية خاطئة لا يوفر تغطية مفيدة. قرارات FFS والإصلاح تحتاج مختصين وبيانات كافية والكود المناسب.', 'A colour matrix alone is not an RBI assessment, and excellent testing for the wrong mechanism gives little value. FFS and repair decisions require competent specialists, adequate data and applicable codes.'),
text('خطان لهما احتمال تسرب متشابه لكن أحدهما يحمل مادة شديدة الخطورة قرب منطقة مأهولة؛ قد تكون أولوية الخطر فيه أعلى بسبب العواقب.', 'Two lines may have similar leakage likelihood, but one carrying a hazardous substance near occupied areas may have higher risk because of consequences.'),
text('هل الفحص يصلح التلف بذاته؟', 'Does inspection itself repair damage?'), [text('نعم', 'Yes'), text('لا؛ يوفر معلومات للتقييم والقرار', 'No; it informs assessment and decisions'), text('إذا كان رقمياً', 'If it is digital')], 1, text('الكشف والتقييم والإصلاح وظائف مختلفة.', 'Detection, assessment and repair are different functions.'), ['rbi', 'api']);

lesson('quality', 'qa_qc', text('QA/QC وITP والتتبّع الفني', 'QA/QC, ITP & technical traceability'), text('حوّل نتيجة الفحص إلى سجل قابل للمراجعة.', 'Turn inspection results into an auditable record.'), text('القياس وقراءة الوثائق', 'Measurement and document reading'),
text('ضمان الجودة QA يهتم بالنظام والعمليات، وضبط الجودة QC يتحقق من مطابقة المخرجات. خطة ITP تربط مراحل العمل بالفحوص والمسؤوليات ونقاط التوقف والشهود والمستندات المطلوبة.', 'QA addresses systems and processes; QC verifies output conformity. An ITP links work stages to inspections, responsibilities, hold and witness points and required records.'),
text('اربط رقم المادة وشهادة الصهر والوصلة والإجراء وإصداره والجهاز ومعايرته والمفتش وتأهيله بالنتيجة. سجل معايير القبول والقيود والخرائط والتوقيعات. عالج عدم المطابقة عبر وصف واضح وتصحيح وتحليل سبب وإجراء مناسب.', 'Link material and heat certificate, weld ID, procedure revision, instrument calibration and inspector qualification to the result. Record acceptance criteria, limitations, maps and approvals. Address nonconformity with clear description, correction, cause analysis and appropriate action.'),
text('ملء النموذج لا يثبت تنفيذ الفحص. لا تعدل نتيجة لإرضاء التسليم؛ أي تعديل يحتاج سبباً وأثراً تدقيقياً وموافقة مناسبة. اعتماد المختبر لا يعني تأهيل كل فرد لكل طريقة.', 'Completing a form does not prove an inspection occurred. Never alter results to satisfy delivery; revisions need reasons, traceability and approval. Laboratory accreditation does not qualify every individual for every method.'),
text('تقرير UT بلا رقم وصلة أو مرجع معايرة لا يسمح بتتبع موثوق، حتى لو احتوى على عبارة «مقبول».', 'A UT report without weld identification or calibration reference is not reliably traceable, even if it says “acceptable”.'),
text('ما الوثيقة التي تربط المراحل بنقاط التوقف والفحوص؟', 'Which document links stages to hold points and inspections?'), [text('ITP', 'ITP'), text('إعلان تسويقي', 'Marketing advertisement'), text('قائمة أسعار', 'Price list')], 0, text('ITP يحدد خطة الفحص والاختبار والمسؤوليات.', 'The ITP defines the inspection and test plan and responsibilities.'), ['iso', 'iaea']);

lesson('safety', 'asset_integrity_rope', text('السلامة وحدود المحاكاة التعليمية', 'Safety & limits of educational simulation'), text('الإشعاع والكهرباء والكيماويات والعمل في الأماكن الخطرة.', 'Radiation, electricity, chemicals and hazardous work areas.'), text('ابدأ بهذا الدرس قبل أي معمل', 'Read before any laboratory'),
text('اختيار وسيلة فحص لا يقتصر على قدرتها على الكشف؛ بل يشمل مخاطر المصدر والطاقة والبيئة والوصول. المحاكاة تشرح المفهوم ولا تمنح تصريح عمل أو كفاءة تشغيل.', 'Method selection includes source, energy, environment and access risks as well as detection capability. Simulation explains concepts; it does not grant a work permit or operating competence.'),
text('العمل الحقيقي يحتاج تقييماً للمخاطر وتصاريح وعزلاً للطاقة وتأهيلاً وإشرافاً وخطة طوارئ تناسب الموقع. في RT يلزم مختصون مرخصون وضوابط مراقبة وتعرض؛ وفي الأماكن المحصورة والارتفاعات يلزم تدريب وإنقاذ متخصص.', 'Real work requires risk assessment, permits, energy isolation, competence, supervision and a site-specific emergency plan. RT requires authorised personnel and exposure controls; confined-space and work-at-height operations require specialist training and rescue arrangements.'),
text('لا تحاول استرجاع مصدر إشعاعي أو دخول منطقة محظورة استناداً إلى درس على الإنترنت. عند الاشتباه في حادث، ابتعد واتبع خطة الموقع وأبلغ المسؤول المختص دون تدخل غير مؤهل.', 'Do not attempt radioactive-source recovery or enter restricted areas based on an online lesson. If an incident is suspected, withdraw, follow the site plan and notify responsible specialists without unqualified intervention.'),
text('نجاحك في محاكي RT لا يسمح لك بتشغيل جهاز أشعة. الخطوة التالية تدريب عملي معتمد ومتطلبات الجهة التنظيمية وصاحب العمل.', 'Passing an RT simulation does not authorise radiation equipment operation. The next step is appropriate supervised practical training and regulator and employer requirements.'),
text('هل اجتياز محاكاة يمنح تصريح عمل ميداني؟', 'Does passing a simulation grant field authorisation?'), [text('نعم', 'Yes'), text('فقط ليلاً', 'Only at night'), text('لا', 'No')], 2, text('التعليم النظري منفصل عن الترخيص والتأهيل العملي والتصاريح.', 'Theory is separate from licensing, practical qualification and work permits.'), ['safety', 'asnt']);

lesson('qualification', 'qa_qc', text('خريطة التأهيل وقراءة الأكواد', 'Qualification map & reading codes'), text('فرّق بين التعلم والشهادة والتفويض.', 'Separate learning, certification and authorisation.'), text('لا توجد متطلبات؛ مناسب لكل المسارات', 'No prerequisites; relevant to every pathway'),
text('SNT-TC-1A توصية لنظام تأهيل وشهادة قائم على صاحب العمل وممارسته المكتوبة. ISO 9712 إطار للشهادة المركزية المستقلة. المتطلبات تختلف حسب الطريقة والمستوى والقطاع والجهة المانحة؛ إنهاء درس لا يساوي Level II أو III.', 'SNT-TC-1A guides employer-based qualification and certification under a written practice. ISO 9712 provides a central independent certification framework. Requirements vary by method, level, sector and certification body; completing a lesson is not Level II or III certification.'),
text('حدد الدور والطريقة ونظام التأهيل، ثم راجع التدريب والخبرة الموثقة والإبصار والاختبارات والتجديد والتفويض المطلوب. في API راجع Body of Knowledge وPublications Effectivity Sheet لنافذة الامتحان. فرق بين كود طريقة الفحص وكود قبول المكون.', 'Choose role, method and certification scheme, then check training, documented experience, vision, examinations, renewal and authorisation requirements. For API consult the Body of Knowledge and Publications Effectivity Sheet for the exam window. Distinguish examination-method rules from component acceptance rules.'),
text('الأكواد غالباً محمية بحقوق نشر؛ استخدم نسخة مرخصة بالإصدار المحدد في العقد. الأرقام الموجودة في المناهج الحالية خطة إرشادية وليست حكماً رسمياً بالأهلية أو ساعات معتمدة.', 'Codes are generally copyrighted; use a licensed copy of the contract-specified edition. Existing curriculum figures are planning guidance, not official eligibility decisions or accredited hours.'),
text('قبل قبول وصلة افحص: كود الإنشاء وإصداره، مرجع طريقة الفحص، الإجراء المعتمد، ثم بند القبول المناسب للخدمة ونوع الوصلة.', 'Before accepting a weld check the construction code and edition, method reference, approved procedure and acceptance clause for the service and joint type.'),
text('هل شهادة حضور دورة تكفي تلقائياً لشهادة NDT مهنية؟', 'Does course attendance automatically give professional NDT certification?'), [text('نعم', 'Yes'), text('لا؛ يلزم استيفاء نظام التأهيل المعني', 'No; the applicable qualification scheme must be fulfilled'), text('نعم لكل الطرق', 'Yes for all methods')], 1, text('التدريب جزء من متطلبات تشمل خبرة واختبارات ومتطلبات أخرى حسب النظام.', 'Training is one part of requirements that include experience, examinations and scheme-specific conditions.'), ['asnt', 'api', 'rbi']);

lesson('lt', 'ndt_advanced', text('اختبار التسرب LT ومعدل التسريب', 'Leak testing & leakage rate'), text('اختيار التقنية بحسب الحساسية ونوع النظام.', 'Select a technique for the sensitivity and system.'), text('الضغط والحرارة والقياس والسلامة', 'Pressure, temperature, measurement and safety'),
text('التسرب انتقال غاز أو سائل خلال مسار نافذ تحت فرق ضغط. معدل التسريب يصف كمية المائع مع الزمن، ولا يساوي قطر الفتحة مباشرة؛ يتأثر بفرق الضغط ونوع المائع وظروف القياس.', 'Leakage is gas or liquid flow through a path under a pressure difference. Leakage rate describes flow over time, not hole diameter directly; it depends on pressure difference, fluid and test conditions.'),
text('توجد تقنيات الفقاعات وتغير الضغط والغاز المتتبع. حدد هل المطلوب تحديد الموقع أم قياس المعدل، ثم الحساسية وزمن الاستقرار والتحقق بمرجع مناسب. اختبار ضغط أو تفريغ فعلي يحتاج خطة معتمدة وضوابط للطاقة المختزنة.', 'Techniques include bubbles, pressure change and tracer gas. Establish whether location or rate is needed, then sensitivity, stabilisation time and reference verification. Actual pressure or vacuum testing requires an approved plan and stored-energy controls.'),
text('تغير حرارة الغاز قد يغير الضغط دون تسرب، كما أن عدم رؤية فقاعات لا يعني صفراً مطلقاً؛ النتيجة محدودة بحساسية التقنية وظروفها.', 'Gas temperature changes can change pressure without leakage, and no visible bubbles does not mean absolute zero leakage; results are limited by technique sensitivity and conditions.'),
text('إذا انخفض الضغط بعد تبريد الغاز، تحقق من الاستقرار الحراري قبل نسبة الانخفاض كله إلى تسرب؛ لا تُعد رفع الضغط دون خطة آمنة.', 'If pressure falls as gas cools, verify thermal stabilisation before attributing the entire drop to leakage; do not repressurise without a safe plan.'),
text('ما عامل قد يغير الضغط دون تسرب؟', 'What can change pressure without a leak?'), [text('درجة الحرارة', 'Temperature'), text('رقم التقرير', 'Report number'), text('لغة الواجهة', 'Interface language')], 0, text('الضغط يعتمد على حالة الغاز وحرارته، لذلك يلزم الاستقرار والتصحيح المناسب.', 'Pressure depends on gas state and temperature, so stabilisation and appropriate correction matter.'), ['lt', 'iaea']);

lesson('ae', 'ndt_advanced', text('الانبعاث الصوتي AE ومراقبة النشاط', 'Acoustic emission & activity monitoring'), text('الاستماع لطاقة تتولد داخل المنشأ.', 'Listen for energy released within a structure.'), text('الموجات والسلامة وآليات التلف', 'Waves, safety and damage mechanisms'),
text('AE يستقبل موجات مرنة عابرة ناتجة عن إطلاق طاقة أثناء تغير أو نمو تلف في المادة. بخلاف UT النشط، يستمع AE إلى نشاط المنشأ تحت ظروف تشغيل أو تحميل محددة بدلاً من إرسال نبضة فحص إلى كل نقطة.', 'AE receives transient elastic waves from energy release during material changes or damage growth. Unlike active UT, it listens to structural activity under defined operating or loading conditions rather than sending an inspection pulse to every location.'),
text('تُستخدم حساسات متعددة وتوقيت الوصول للمساعدة في تحديد مواقع المصادر. تحقق من الاقتران واستجابة القنوات وسرعة الانتشار والضوضاء. قد تحدد النتائج منطقة تحتاج فحصاً موضعياً مكملاً لتوصيف التلف.', 'Multiple sensors and arrival times help locate sources. Verify coupling, channel response, propagation velocity and noise. Results may identify an area needing complementary local examination to characterise damage.'),
text('العيب غير النشط قد لا يرسل إشارة، والاحتكاك والضوضاء قد يقلدان نشاط التلف. لا ترفع الحمل أو الضغط لتحفيز الإشارات خارج خطة معتمدة.', 'An inactive flaw may produce no signal; friction and noise can resemble damage activity. Never increase loading or pressure to stimulate signals outside an approved plan.'),
text('تجمع أحداث قرب دعامة قد يكون نشاط تلف أو احتكاكاً؛ راجع التوقيت والتحميل والموقع ثم استخدم وسيلة تحقق مناسبة.', 'An event cluster near a support may indicate damage or friction; review timing, loading and location, then use suitable verification.'),
text('هل غياب أحداث AE يثبت عدم وجود كل العيوب؟', 'Does absence of AE events prove absence of all flaws?'), [text('نعم', 'Yes'), text('لا؛ العيوب قد تكون غير نشطة', 'No; flaws may be inactive'), text('نعم إذا كانت الشاشة واضحة', 'Yes if the display is clear')], 1, text('AE حساس للنشاط أثناء ظروف الاختبار وليس جرداً لكل عيب ساكن.', 'AE detects activity under test conditions, not every dormant flaw.'), ['ae']);

lesson('vt_geometry', 'conventional_ndt', text('VT: قياس هندسة الوصلة وقبولها', 'VT: weld geometry measurement & acceptance'), text('حوّل ملاحظة بصرية إلى قياس موثق وقرار قبول.', 'Turn a visual observation into a documented measurement and acceptance decision.'), text('الوحدات والقياس والفحص البصري', 'Units, measurement and visual testing'),
text('هندسة الوصلة (misalignment Hi-Lo، undercut depth، cap height، toe angle) تُقاس بأدوات معايرة (Cambridge gauge، Hi-Lo gauge). القياس يُسجّل بالوحدات والدقة والمرجع؛ قرار القبول يُتخذ وفق الكود (ASME/AWS/API) ونوع الخدمة.', 'Joint geometry (misalignment Hi-Lo, undercut depth, cap height, toe angle) is measured with calibrated gauges (Cambridge, Hi-Lo). Measurements are recorded with units, resolution and reference; acceptance follows the applicable code (ASME/AWS/API) and service type.'),
text('راجع الرسم وهوية الوصلة ومرحلة الفحص. نظف السطح، تحقق من الإضاءة والأداة، قِس في 3 مواضع على الأقل، سجّل القيم والوحدات ورقم الأداة ومرجع البند. قارن بالحد (limit) في الكود (مثلاً undercut ≤ 1mm for certain categories). افصل الملاحظة عن قرار القبول.', 'Review drawing, weld ID and inspection stage. Clean surface, verify lighting and gauge, measure at ≥3 locations, record values, units, gauge ID and clause reference. Compare to code limit (e.g., undercut ≤ 1 mm for certain categories). Separate observation from acceptance decision.'),
text('لا تطبق حدود كود على مشروع يستخدم كوداً آخر. لا تعمّم "مقبول" دون قياس. الوصول المحدود قد يستلزم منظاراً أو طريقة مكملة.', 'Do not apply one code’s limits to a project using another code. Do not generalise "acceptable" without measurement. Limited access may require a borescope or complementary method.'),
text('وصلة W-12: Hi-Lo = 0.8 mm (حد 1.0)، undercut = 0.5 mm (حد 1.0)، cap height = 2.0 mm (حد 3.0). قرار: مقبول وفق AWS D1.1 (مثال تعليمي).', 'Weld W-12: Hi-Lo = 0.8 mm (limit 1.0), undercut = 0.5 mm (limit 1.0), cap height = 2.0 mm (limit 3.0). Decision: acceptable per AWS D1.1 (educational example).'),
text('أي خطوة تسبق قرار القبول؟', 'Which step precedes the acceptance decision?'),
[text('التصوير', 'Photography'), text('القياس والتوثيق', 'Measurement & documentation'), text('الطلاء', 'Painting')], 1,
text('القياس والتوثيق (وحدات، دقة، مرجع) يسبقان قرار القبول.', 'Measurement and documentation (units, resolution, reference) precede acceptance.'),
['asnt', 'iaea']);
